// Package v1 release-promotion queries. These endpoints are read-only views
// over existing release records grouped by a batch identifier: they never
// write or rewrite history and produce the same response for the same input.
package v1

import (
	"net/http"
	"sort"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/deployment-tracker/internal/store"
)

// Error codes for batch-scoped promotion queries.
const (
	codeDuplicatePromotionEnv = "DUPLICATE_PROMOTION_ENVIRONMENT"
	codeUnknownPromotionEnv   = "UNKNOWN_PROMOTION_ENVIRONMENT"
)

type releaseFactView struct {
	Environment   string            `json:"environment"`
	Version       string            `json:"version"`
	GateStatus    string            `json:"gate_status"`
	RollbackPoint string            `json:"rollback_point"`
	Changes       []changeEntryView `json:"changes"`
	RecordedAt    string            `json:"recorded_at"`
}

type inconsistentChangeView struct {
	ChangeID string            `json:"change_id"`
	Before   changeEntryView   `json:"before"`
	After    changeEntryView   `json:"after"`
}

type scalarConflictView struct {
	Before   string `json:"before"`
	After    string `json:"after"`
	Conflict bool   `json:"conflict"`
}

// promotionSegmentView is one adjacent-environment diff. Every change list
// is always present (empty when nothing falls in that category) and ordered
// by the stable change identifier (title).
type promotionSegmentView struct {
	FromEnvironment       string                   `json:"from_environment"`
	ToEnvironment         string                   `json:"to_environment"`
	FromVersion           string                   `json:"from_version"`
	ToVersion             string                   `json:"to_version"`
	VersionDiverged       bool                     `json:"version_diverged"`
	AddedChanges          []changeEntryView        `json:"added_changes"`
	MissingChanges        []changeEntryView        `json:"missing_changes"`
	InconsistentChanges   []inconsistentChangeView `json:"inconsistent_changes"`
	GateStatusConflict    scalarConflictView       `json:"gate_status_conflict"`
	RollbackPointConflict scalarConflictView       `json:"rollback_point_conflict"`
}

type promotionNodeView struct {
	Environment string            `json:"environment"`
	Releases    []releaseFactView `json:"releases"`
}

type promotionChainView struct {
	BatchID      string                 `json:"batch_id"`
	Environments []string               `json:"environments"`
	Nodes        []promotionNodeView    `json:"nodes"`
	SegmentDiffs []promotionSegmentView `json:"segment_diffs"`
	Consistent   bool                   `json:"consistent"`
}

type promotionDiffView struct {
	BatchID        string               `json:"batch_id"`
	FromEnvironment string             `json:"from_environment"`
	ToEnvironment  string               `json:"to_environment"`
	FromRelease    releaseFactView      `json:"from_release"`
	ToRelease      releaseFactView      `json:"to_release"`
	SegmentDiff    promotionSegmentView `json:"segment_diff"`
	Consistent     bool                 `json:"consistent"`
}

type changeTraceView struct {
	BatchID                 string   `json:"batch_id"`
	ChangeID                string   `json:"change_id"`
	Environments            []string `json:"environments"`
	FirstEnteredEnvironment string   `json:"first_entered_environment"`
	FirstEnteredAt          string   `json:"first_entered_at"`
	PassedEnvironments      []string `json:"passed_environments"`
	FirstMissingEnvironment string   `json:"first_missing_environment"`
}

// promotionContext is the validated, batch-scoped data shared by all chain
// queries. Releases per node are stored newest-first; effective maps a node
// to its latest release fact.
type promotionContext struct {
	batchID   string
	sequence  []string
	byNode    map[string][]*store.ReleaseRecord
	effective map[string]*store.ReleaseRecord
}

// getPromotionChain links one batch across an ordered environment sequence.
func getPromotionChain(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := c.Param("batch_id")
		sequence, ok := parsePromotionSequence(c, deps, c.Query("environments"))
		if !ok {
			return
		}
		promotion, ok := loadPromotionContext(c, deps, batchID, sequence)
		if !ok {
			return
		}
		segments := buildSegments(promotion)
		c.JSON(http.StatusOK, promotionChainView{
			BatchID:      batchID,
			Environments: sequence,
			Nodes:        buildNodes(promotion),
			SegmentDiffs: segments,
			Consistent:   len(segments) == 0,
		})
	}
}

// getPromotionDiff returns the local promotion diff between any two nodes of
// the batch's environment sequence.
func getPromotionDiff(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := c.Param("batch_id")
		from := strings.TrimSpace(c.Query("from"))
		to := strings.TrimSpace(c.Query("to"))
		if from == "" || to == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidPromotionSequenceV1,
				"from and to query parameters are required")
			return
		}
		if from == to {
			fail(c, http.StatusBadRequest, store.CodeSamePromotionNodeV1,
				"cannot diff environment "+from+" against itself")
			return
		}
		sequence, ok := parsePromotionSequence(c, deps, from+","+to)
		if !ok {
			return
		}
		promotion, ok := loadPromotionContext(c, deps, batchID, sequence)
		if !ok {
			return
		}
		segment := diffPromotionNodes(promotion.effective[from], promotion.effective[to])
		c.JSON(http.StatusOK, promotionDiffView{
			BatchID:         batchID,
			FromEnvironment: from,
			ToEnvironment:   to,
			FromRelease:     toReleaseFactView(promotion.effective[from]),
			ToRelease:       toReleaseFactView(promotion.effective[to]),
			SegmentDiff:     segment,
			Consistent:      segmentIsConsistent(segment),
		})
	}
}

// getChangeTrace locates one change entry (identified by title) across the
// batch: where it first entered, every node it passed, and where it first
// went missing afterwards.
func getChangeTrace(deps Dependencies) gin.HandlerFunc {
	return func(c *gin.Context) {
		batchID := c.Param("batch_id")
		changeID := strings.TrimSpace(c.Query("change"))
		if changeID == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidPromotionSequenceV1,
				"change query parameter is required")
			return
		}
		sequence, ok := parsePromotionSequence(c, deps, c.Query("environments"))
		if !ok {
			return
		}
		promotion, ok := loadPromotionContext(c, deps, batchID, sequence)
		if !ok {
			return
		}
		presentAt := map[string]bool{}
		for _, env := range sequence {
			presentAt[env] = effectiveHasChange(promotion.effective[env], changeID)
		}
		firstEntered := -1
		for i, env := range sequence {
			if presentAt[env] {
				firstEntered = i
				break
			}
		}
		if firstEntered == -1 {
			fail(c, http.StatusNotFound, store.CodePromotionChangeNotFoundV1,
				"change "+changeID+" does not enter batch "+batchID)
			return
		}
		passed := []string{}
		firstMissing := ""
		for i := firstEntered; i < len(sequence); i++ {
			env := sequence[i]
