// parsePromotionSequence validates the ordered environment list from the
// "environments" query parameter: non-empty comma-separated registered
// environment keys with no duplicates. Problems are reported as BadRequest
// with the offending environment named explicitly.
func parsePromotionSequence(c *gin.Context, deps Dependencies, raw string) ([]string, bool) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		fail(c, http.StatusBadRequest, store.CodeInvalidPromotionSequenceV1,
			"environments query parameter is required")
		return nil, false
	}
	parts := strings.Split(raw, ",")
	sequence := make([]string, 0, len(parts))
	for _, part := range parts {
		env := strings.TrimSpace(part)
		if env == "" {
			fail(c, http.StatusBadRequest, store.CodeInvalidPromotionSequenceV1,
				"environment sequence must not contain empty entries")
			return nil, false
		}
		sequence = append(sequence, env)
	}
	seen := map[string]bool{}
	for _, env := range sequence {
		if seen[env] {
			fail(c, http.StatusBadRequest, codeDuplicatePromotionEnv,
				"environment sequence contains a duplicate environment: "+env)
			return nil, false
		}
		seen[env] = true
	}
	for _, env := range sequence {
		exists, err := deps.Store.TrackedEnvironmentExists(env)
		if err != nil {
			failStorage(c)
			return nil, false
		}
		if !exists {
			fail(c, http.StatusBadRequest, codeUnknownPromotionEnv,
				"environment sequence contains an unknown environment: "+env)
			return nil, false
		}
	}
	return sequence, true
}

// loadPromotionContext verifies the batch exists and that every requested
// node carries at least one release fact for it. A node without facts cannot
