func loadPromotionContext(c *gin.Context, deps Dependencies, batchID string, sequence []string) (*promotionContext, bool) {
	exists, err := deps.Store.ReleaseBatchExists(batchID)
	if err != nil {
		failStorage(c)
		return nil, false
	}
	if !exists {
		fail(c, http.StatusNotFound, store.CodeReleaseBatchNotFoundV1,
			"no release batch with id "+batchID)
		return nil, false
	}
	records, err := deps.Store.ListReleaseRecords(store.ReleaseRecordFilter{BatchID: batchID})
	if err != nil {
		failStorage(c)
		return nil, false
	}
	byNode := map[string][]*store.ReleaseRecord{}
	for i := range records {
		record := &records[i]
		if _, wanted := indexInSequence(sequence, record.Environment); wanted {
			byNode[record.Environment] = append(byNode[record.Environment], record)
		}
	}
	missing := []string{}
	for _, env := range sequence {
		if len(byNode[env]) == 0 {
			missing = append(missing, env)
		}
	}
	if len(missing) > 0 {
		fail(c, http.StatusConflict, store.CodePromotionOrderConflictV1,
			"release facts do not determine the promotion order for node(s): "+strings.Join(missing, ", "))
		return nil, false
	}
	effective := make(map[string]*store.ReleaseRecord, len(sequence))
	for _, env := range sequence {
		// ListReleaseRecords is newest-first, so the first entry is the
		// latest release fact for the node.
		effective[env] = byNode[env][0]
	}
	return &promotionContext{
		batchID:   batchID,
		sequence:  sequence,
		byNode:    byNode,
		effective: effective,
	}, true
}

func indexInSequence(sequence []string, env string) (int, bool) {
	for i, candidate := range sequence {
		if candidate == env {
			return i, true
		}
	}
	return -1, false
}

