// parsePromotionEnvironments splits the ordered environment sequence and
// reports duplicates and unknown (unregistered) entries. It returns the
// trimmed sequence in request order.
func parsePromotionEnvironments(c *gin.Context, deps Dependencies, raw string) ([]string, bool) {
	tokens := strings.Split(raw, ",")
	environments := make([]string, 0, len(tokens))
	for _, token := range tokens {
		environments = append(environments, strings.TrimSpace(token))
	}
	if len(environments) == 0 || environments[0] == "" {
		fail(c, http.StatusBadRequest, store.CodePromotionSequenceInvalidV1,
			"the environments query parameter must list at least one environment")
		return nil, false
	}
	for _, environment := range environments {
		if environment == "" {
			fail(c, http.StatusBadRequest, store.CodePromotionSequenceInvalidV1,
				"the environments query parameter contains an empty environment")
			return nil, false
		}
	}
	seen := map[string]bool{}
	var duplicates []string
	for _, environment := range environments {
		if seen[environment] {
			duplicates = append(duplicates, environment)
			continue
		}
		seen[environment] = true
	}
	if len(duplicates) > 0 {
		sort.Strings(duplicates)
		fail(c, http.StatusBadRequest, store.CodePromotionSequenceInvalidV1,
			"the environments sequence contains duplicate environment(s): "+strings.Join(uniqueSorted(duplicates), ", "))
		return nil, false
	}
	var unknown []string
	for _, environment := range environments {
		exists, err := deps.Store.TrackedEnvironmentExists(environment)
		if err != nil {
			failStorage(c)
			return nil, false
		}
		if !exists {
			unknown = append(unknown, environment)
		}
	}
	if len(unknown) > 0 {
		sort.Strings(unknown)
		fail(c, http.StatusBadRequest, store.CodePromotionSequenceInvalidV1,
			"the environments sequence contains unknown environment(s): "+strings.Join(uniqueSorted(unknown), ", "))
		return nil, false
	}
	return environments, true
}

// uniqueSorted dedupes and sorts a small slice of environment keys.
func uniqueSorted(values []string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if !seen[value] {
			seen[value] = true
			out = append(out, value)
		}
	}
	sort.Strings(out)
	return out
}

