// groupBatchNodes groups batch records by environment and returns every node
// with its releases oldest first. Records sharing a recorded_at timestamp
// break ties by internal insertion order, preserving registration order.
func groupBatchNodes(records []store.ReleaseRecord, environments []string) map[string][]store.ReleaseRecord {
	grouped := make(map[string][]store.ReleaseRecord, len(environments))
	for i := range records {
		grouped[records[i].Environment] = append(grouped[records[i].Environment], records[i])
	}
	for environment := range grouped {
		oldestFirst := grouped[environment]
		sort.SliceStable(oldestFirst, func(i, j int) bool {
			if oldestFirst[i].RecordedAt != oldestFirst[j].RecordedAt {
				return oldestFirst[i].RecordedAt < oldestFirst[j].RecordedAt
			}
			return false
		})
		grouped[environment] = oldestFirst
	}
	return grouped
}

