// in the batch, in request order and deduplicated.
func missingBatchNodes(grouped map[string][]store.ReleaseRecord, environments []string) []string {
	missing := make([]string, 0)
	seen := map[string]bool{}
	for _, environment := range environments {
		if len(grouped[environment]) == 0 && !seen[environment] {
			missing = append(missing, environment)
			seen[environment] = true
		}
	}
	return missing
}

// failOnMissingNodes writes PROMOTION_ORDER_CONFLICT when the recorded facts
// cannot determine the position of the given nodes in the chain.
func failOnMissingNodes(c *gin.Context, missing []string) bool {
	if len(missing) == 0 {
