// the upstream -> downstream direction.
func diffPromotionSegment(fromEnvironment, toEnvironment string, from, to *store.ReleaseRecord) promotionDiffView {
	diff := promotionDiffView{
		FromEnvironment:     fromEnvironment,
		ToEnvironment:       toEnvironment,
		FromVersion:         from.Version,
		ToVersion:           to.Version,
		VersionDiverged:     from.Version != to.Version,
		AddedChanges:        []changeEntryView{},
		MissingChanges:      []changeEntryView{},
		InconsistentChanges: []changedEntryView{},
		GateStatus: promotionConflictView{
			From:      fromEnvironment,
			To:        toEnvironment,
			FromValue: from.GateStatus,
			ToValue:   to.GateStatus,
			Conflict:  from.GateStatus != to.GateStatus,
		},
		RollbackPoint: promotionConflictView{
			From:      fromEnvironment,
			To:        toEnvironment,
			FromValue: from.RollbackPoint,
			ToValue:   to.RollbackPoint,
			Conflict:  from.RollbackPoint != to.RollbackPoint,
		},
	}
	fromEntries := indexEntries(from.Changes)
	toEntries := indexEntries(to.Changes)
	for title, entry := range toEntries {
		upstream, present := fromEntries[title]
		if !present {
			diff.AddedChanges = append(diff.AddedChanges, toChangeEntryView(entry))
			continue
