	}
	for title, entry := range fromEntries {
		if _, present := toEntries[title]; !present {
			diff.MissingChanges = append(diff.MissingChanges, toChangeEntryView(entry))
		}
	}
	sortEntriesByTitle(diff.AddedChanges)
	sortEntriesByTitle(diff.MissingChanges)
	sort.Slice(diff.InconsistentChanges, func(i, j int) bool {
		return diff.InconsistentChanges[i].Left.Title < diff.InconsistentChanges[j].Left.Title
	})
	return diff
}

// sortEntriesByTitle orders change entries by their stable title identifier.
func sortEntriesByTitle(entries []changeEntryView) {
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Title < entries[j].Title
	})
}

